/* Reset Global e Box Sizing */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Seletor por Tag (Especificidade: 0,0,1) */
p {
  color: #333333;
}

/* Seletor por Classe (Especificidade: 0,1,0) */
.card-title {
  color: #6750A4;
  font-size: 1.25rem;
}

/* Seletor por ID (Especificidade: 1,0,0) */
#main-banner {
  background-color: #F3EDF7;
  padding: 24px;
  border-radius: 16px;
}
